ulimit -c 0; npm run build && node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
const s = new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep'}}); s.allowErrorProps('stackFrames');
const error = new Error('outer', {cause:new Error('inner')});
const result = new SuperJSON().deserialize(s.serialize(error));
assert(result.cause instanceof Error);
assert.equal(result.cause.message, 'inner');
console.log('Cross-instance cause round trip passed');
EOF
